            k = clamp(0.8 * c_err / 45.0, -1.0, 1.0)
            left = 0.5 - k
            right = 0.5 + k
            return (clamp(left, -1.0, 1.0), clamp(right, -1.0, 1.0))
        if c_err > 0.0:
            return (-1.0, -0.3)
        return (-0.3, -1.0)

    if abs(err) > 50.0:
        if err > 0.0:
            return (-0.3, 1.0)
        return (1.0, -0.3)

    if dist > 1.8:
        base = 1.0
    elif dist > 1.5:
        base = 0.7
    elif dist > 1.2:
        base = 0.4
    elif dist > 0.9:
        base = 0.3
    else:
        base = -0.5

    k = clamp(0.8 * err / 45.0, -1.0, 1.0)

    if r > 5.0:
        if abs(c_err) > 25.0:
            if abs(c_err) > 90.0:
                if c_err > 0.0:
                    return (-0.8, -0.2)
                return (-0.2, -0.8)
            if c_err > 0.0:
                return (-0.2, 0.8)
            return (0.8, -0.2)
