def drive(me, enemy, arena):
    if me.inverted:
        return (1, 1)
    elif me.airborne:
        return (0, 0)
    else:
        # Move toward the enemy
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        distance = (dx**2 + dy**2)**0.5

        if distance > 0:
            target_heading = bearing_to(enemy.x, enemy.y)
            turn_rate = target_heading - me.heading
            turn_rate = (turn_rate + 180) % 360 - 180  # Normalize to -180 to 180

            if abs(turn_rate) > 5:
                # Turn toward the enemy
                turn_speed = min(1, abs(turn_rate) / 10)
                left = 1 if turn_rate > 0 else -1
                right = -left
                return (left * turn_speed, right * turn_speed)
            else:
                # Move forward
                return (0.5, 0.5)
        else:
            return (0, 0)

